#include <limits>
#include <iostream>
#include <string>

int main() {
    // Specialization exists for int
    if (std::numeric_limits<int>::is_specialized) {
        std::cout << "Int limits are specialized.\n";
    }

    // Specialization does not exist for std::string
    if (!std::numeric_limits<std::string>::is_specialized) {
        std::cout << "String limits are NOT specialized.\n";
        // Accessing max() here would be undefined/meaningless
    }
}
